begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,request_id uuid,stop_id uuid,recover_id uuid,token uuid,input jsonb,manifest jsonb,proof jsonb,stamp timestamptz);
insert into fixture select gen_random_uuid(),id,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,'{"request":{"modality":"image","prompt":"Generate a simple abstract community campaign background","tier":"final","aspectRatio":"1:1","altText":"Abstract background","name":"Generated fixture","maxCostUsd":1},"model":"fixture/model","estimatedCostUsd":0.04,"modelPolicyVersion":"fixture"}',jsonb_build_object('contentHash',repeat('a',64),'size',100,'mimeType','image/png','extension','png','width',2,'height',2),null,null from public.profiles where id='11111111-1111-1111-1111-111111111111';
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222','ForgeStudio media rollback fixture' from fixture;
do $$declare f fixture;r jsonb;begin select * into f from fixture;
 perform pg_temp.check(public.begin_forgestudio_media(f.request_id,f.property_id,gen_random_uuid(),f.input)->>'state'='forbidden','media request requires current property access');
 r:=public.begin_forgestudio_media(f.request_id,f.property_id,f.actor_id,f.input);
 perform pg_temp.check(r->>'state'='saved','request and job are saved atomically');
 perform pg_temp.check(public.begin_forgestudio_media(f.request_id,f.property_id,f.actor_id,f.input)->>'state'='replayed','lost request response returns the original job');
 perform pg_temp.check(public.begin_forgestudio_media(f.request_id,f.property_id,f.actor_id,jsonb_set(f.input,'{request,prompt}','"Different generated artwork request"'))->>'state'='request_conflict','another request cannot reuse the same identity');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where property_id=f.property_id and action='studio.media.requested'),'request decision is recorded once');
 perform pg_temp.check(not has_table_privilege('authenticated','public.forgestudio_media_requests','select') and not has_function_privilege('authenticated','public.advance_forgestudio_media(uuid,uuid,text,jsonb)','execute'),'media evidence and transitions remain private');
 r:=public.claim_forgestudio_media('fixture-worker');
 perform pg_temp.check(r->>'state'='claimed' and r->'request'->>'id'=f.request_id::text,'worker claims the saved request');
 update fixture set token=(r->'request'->>'claim_token')::uuid;
 perform pg_temp.check(public.claim_forgestudio_media('second-worker')->>'state'='empty','an active worker cannot be claimed twice');
end$$;
do $$declare f fixture;r jsonb;begin select * into f from fixture;
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,gen_random_uuid(),'model_intent','{}')->>'state'='claim_mismatch','wrong worker token cannot start a model');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'result_manifest',f.manifest)->>'state'='intent_required','model result requires saved model intent');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'model_intent','{}')->>'state'='proceed_once','exact worker receives one model permission');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'model_intent','{}')->>'state'='already_started','lost model permission cannot authorize another invocation');
 update public.forgestudio_media_requests set lease_expires_at=clock_timestamp()-interval '1 minute' where id=f.request_id;
 perform pg_temp.check(public.claim_forgestudio_media('late-worker')->>'state'='empty','lease expiry never replays a model intent');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'failure','{"code":"model_uncertain"}')->>'state'='saved','unknown model outcome is held');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'failure','{"code":"model_uncertain"}')->>'state'='saved' and(select count(*)=1 from public.forgestudio_media_receipts where request_id=f.request_id and kind='failure'),'repeated failure receipt cannot duplicate evidence');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'result_manifest',f.manifest)->>'state'='saved','late model manifest is retained after worker uncertainty');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'result_manifest',f.manifest)->>'state'='replayed','identical manifest acknowledgement is recoverable');
 perform pg_temp.check(public.advance_forgestudio_media(f.request_id,f.token,'result_manifest',f.manifest||jsonb_build_object('contentHash',repeat('b',64)))->>'state'='result_conflict','a different result cannot replace saved model bytes');
 update fixture set proof=jsonb_build_object('contentHash',repeat('a',64),'storageBucket','property-assets','storagePath',f.property_id||'/forgestudio/generated/'||f.request_id||'.png','storageVerified',true,'fileUrl','https://example.invalid/generated.png'),stamp=(select updated_at from public.forgestudio_media_requests where id=f.request_id);
end$$;
create function pg_temp.fail_media_history() returns trigger language plpgsql as $$begin if new.action='studio.media.completed' then raise exception 'Fixture media history failure';end if;return new;end$$;
create trigger media_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_media_history();
do $$declare f fixture;begin select * into f from fixture;
 begin perform public.finish_forgestudio_media(f.request_id,f.property_id,f.actor_id,f.proof);raise exception 'FAIL partial asset';exception when raise_exception then if SQLERRM<>'Fixture media history failure' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.content_assets where id=f.request_id) and (select state='result_ready' from public.forgestudio_media_requests where id=f.request_id),'action history failure rolls back generated asset and completion');
end$$;
drop trigger media_fixture_failure on public.shared_action_events;
do $$declare f fixture;r jsonb;payload jsonb;begin select * into f from fixture;
 payload:=jsonb_build_object('jobId',f.request_id,'action','recover','expectedUpdatedAt',f.stamp,'reason','Verified saved model file after interrupted storage','storage',f.proof);
 perform pg_temp.check(public.decide_forgestudio_media(f.recover_id,f.property_id,f.actor_id,payload)->>'state'='saved','reviewed file recovery completes the same request');
 perform pg_temp.check(public.decide_forgestudio_media(f.recover_id,f.property_id,f.actor_id,payload)->>'state'='replayed','lost recovery acknowledgement returns one result');
 perform pg_temp.check((select approval_status='pending' and rights_status='generated' and content_hash=repeat('a',64) and is_ai_generated and org_id='22222222-2222-2222-2222-222222222222' from public.content_assets where id=f.request_id),'generated asset records origin and exact bytes pending usage review');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where property_id=f.property_id and action='studio.media.completed'),'generated asset and completion record commit once');
 perform pg_temp.check((select e.origin='workflow' from public.shared_action_episodes e join public.shared_action_events a on a.episode_id=e.id where a.property_id=f.property_id and a.action='studio.media.completed'),'automated completion is distinguished from a console decision');
 begin update public.content_assets set file_url='https://example.invalid/changed.png' where id=f.request_id;raise exception 'FAIL mutable file';exception when raise_exception then if SQLERRM not like 'Archive this saved asset%' then raise;end if;end;
 perform pg_temp.check(true,'saved generated file cannot change in place');
end$$;
-- Stop after intent: a later result remains private and cannot create an asset.
do $$declare f fixture;r jsonb;request_uuid uuid:=gen_random_uuid();token uuid;stamp timestamptz;payload jsonb;begin select * into f from fixture;
 perform public.begin_forgestudio_media(request_uuid,f.property_id,f.actor_id,f.input);r:=public.claim_forgestudio_media('stop-worker');token:=(r->'request'->>'claim_token')::uuid;perform public.advance_forgestudio_media(request_uuid,token,'model_intent','{}');select updated_at into stamp from public.forgestudio_media_requests where id=request_uuid and property_id=f.property_id;
 payload:=jsonb_build_object('jobId',request_uuid,'action','stop','expectedUpdatedAt',stamp,'reason','Stop remaining media work');
 perform pg_temp.check(public.decide_forgestudio_media(f.stop_id,f.property_id,f.actor_id,payload||jsonb_build_object('expectedUpdatedAt',stamp-interval '1 second'))->>'state'='stale_request','stop decision must match the saved request version');
 perform pg_temp.check(public.decide_forgestudio_media(f.stop_id,f.property_id,f.actor_id,payload)->>'state'='saved','stop is an atomic saved decision');
 perform pg_temp.check(public.decide_forgestudio_media(f.stop_id,f.property_id,f.actor_id,payload)->>'state'='replayed','lost stop response is recoverable');
 perform pg_temp.check(public.advance_forgestudio_media(request_uuid,token,'result_manifest',f.manifest)->>'state'='saved','late stopped result retains its byte manifest');
 perform pg_temp.check(public.finish_forgestudio_media(request_uuid,f.property_id,f.actor_id,f.proof)->>'state'='stopped' and not exists(select 1 from public.content_assets a where a.id=request_uuid),'late result cannot add an asset after stop');
end$$;
-- A changed source cannot authorize model work; advisory rights changes do not block it.
do $$declare f fixture;source uuid:=gen_random_uuid();request_uuid uuid:=gen_random_uuid();claim jsonb;token uuid;payload jsonb;begin select * into f from fixture;
 insert into public.content_assets(id,property_id,name,file_url,asset_type,approval_status,rights_status)values(source,f.property_id,'Source fixture','https://example.invalid/source.jpg','image','approved','owned');
 payload:=jsonb_set(f.input,'{request,sourceAssetId}',to_jsonb(source));
 perform public.begin_forgestudio_media(request_uuid,f.property_id,f.actor_id,payload);claim:=public.claim_forgestudio_media('source-worker');token:=(claim->'request'->>'claim_token')::uuid;
 update public.content_assets set approval_status='rejected' where id=source;
 perform pg_temp.check(public.advance_forgestudio_media(request_uuid,token,'model_intent','{}')->>'state'='source_changed','withdrawn source approval holds the model before any invocation');
 perform public.advance_forgestudio_media(request_uuid,token,'failure','{"code":"source_changed"}');
 update public.content_assets set approval_status='approved' where id=source;request_uuid:=gen_random_uuid();perform public.begin_forgestudio_media(request_uuid,f.property_id,f.actor_id,payload);claim:=public.claim_forgestudio_media('advisory-worker');token:=(claim->'request'->>'claim_token')::uuid;
 update public.content_assets set rights_status='restricted',expires_at=clock_timestamp()-interval '1 day' where id=source;
 perform pg_temp.check(public.advance_forgestudio_media(request_uuid,token,'model_intent','{}')->>'state'='proceed_once','rights and expiry remain advisories under ForgeStudio policy');
end$$;
-- A preparation lease can be reclaimed, but only the newest token can start work.
do $$declare f fixture;request_uuid uuid:=gen_random_uuid();claim jsonb;old_token uuid;new_token uuid;begin select * into f from fixture;
 perform public.begin_forgestudio_media(request_uuid,f.property_id,f.actor_id,f.input);claim:=public.claim_forgestudio_media('expired-preparation');old_token:=(claim->'request'->>'claim_token')::uuid;
 update public.forgestudio_media_requests set lease_expires_at=clock_timestamp()-interval '1 minute' where id=request_uuid;
 claim:=public.claim_forgestudio_media('new-preparation');new_token:=(claim->'request'->>'claim_token')::uuid;
 perform pg_temp.check(new_token<>old_token,'expired preparation gets a new worker token');
 perform pg_temp.check(public.advance_forgestudio_media(request_uuid,old_token,'model_intent','{}')->>'state'='claim_mismatch','superseded preparation token cannot start a model');
 perform pg_temp.check(public.advance_forgestudio_media(request_uuid,new_token,'model_intent','{}')->>'state'='proceed_once','new preparation owns the one model intent');
end$$;
-- Result promotion must still belong to the same client organization.
do $$declare f fixture;request_uuid uuid:=gen_random_uuid();claim jsonb;token uuid;begin select * into f from fixture;
 perform public.begin_forgestudio_media(request_uuid,f.property_id,f.actor_id,f.input);claim:=public.claim_forgestudio_media('scope-worker');token:=(claim->'request'->>'claim_token')::uuid;perform public.advance_forgestudio_media(request_uuid,token,'model_intent','{}');perform public.advance_forgestudio_media(request_uuid,token,'result_manifest',f.manifest);
 perform pg_temp.check(public.finish_forgestudio_media(request_uuid,f.property_id,gen_random_uuid(),f.proof)->>'state'='forbidden','another client cannot recover private generated bytes');
 begin update public.forgestudio_media_requests set result_manifest=f.manifest||'{"size":900}' where id=request_uuid;raise exception 'FAIL mutable result';exception when raise_exception then if SQLERRM<>'Media input, output and terminal decisions are immutable' then raise;end if;end;
 perform pg_temp.check(true,'saved media manifest cannot be changed in place');
end$$;
select count(*) as passed_assertions from checks;
rollback;
